describe("doctests of sympy.stats.compound_rv", () => {
  it("C.set", () => {
    const X = new Sym('X');
    expect(sympyStr(new CompoundDistribution([new NormalDistribution([new RandomSymbol(X, new SingleContinuousPSpace([X, new NormalDistribution([rational(2), rational(4)])])), rational(4)])]).set)).toBe('Interval(-oo, oo)');
  });
  it("C.pdf(x, evaluate=True).simplify()", () => {
    const x = new Sym('x');
    expect(sympyStr(simplify(add(mul(rational(1, 2), pow(pi, rational(-3, 2)), pow(add(2, mul(-1, x)), -1), add(mul(rational(1, 8), pi, add(2, mul(-1, x)), exp(mul(rational(1, 64), pow(add(2, mul(-1, x)), 2)))), mul(rational(1, 8), pi, add(2, mul(-1, x)), fn('erf', [add(rational(-1, 4), mul(rational(1, 8), x))]), exp(mul(rational(1, 64), pow(add(2, mul(-1, x)), 2))))), exp(add(rational(-1, 8), mul(rational(-1, 32), pow(x, 2)), mul(rational(1, 8), x)))), mul(rational(-1, 2), pow(pi, rational(-3, 2)), pow(add(2, mul(-1, x)), -1), add(mul(rational(-1, 8), pi, add(2, mul(-1, x)), exp(mul(rational(1, 64), pow(add(2, mul(-1, x)), 2)))), mul(rational(1, 8), pi, add(2, mul(-1, x)), fn('erf', [add(rational(-1, 4), mul(rational(1, 8), x))]), exp(mul(rational(1, 64), pow(add(2, mul(-1, x)), 2))))), exp(add(rational(-1, 8), mul(rational(-1, 32), pow(x, 2)), mul(rational(1, 8), x)))))))).toBe('exp(-x**2/64 + x/16 - 1/16)/(8*sqrt(pi))');
  });
});

